/** Case-insensitive lookup used to refuse inviting an address that is already a member. */
export async function findActiveMemberByEmail(
  orgId: OrgId,
  email: string,
): Promise<Member | null> {
  const row = getDb()
    .select({ member: members })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
        eq(users.email, email.toLowerCase()),
      ),
    )
    .get();
  return row ? toMember(row.member) : null;
}

