/**
 * Refuses the whole batch, up front, when it names the same address twice, or
 * an address that already belongs to a current member, or one that already
 * has a pending invitation. Comparisons ignore letter case, and a refusal
 * here means nothing in the batch is created.
 */
async function assertInvitableBatch(
  orgId: InviteMembersInput["orgId"],
  invites: InviteMembersInput["invites"],
): Promise<void> {
  const seen = new Set<string>();

  for (const invite of invites) {
    const normalized = invite.email.toLowerCase();

    if (seen.has(normalized)) {
      throw new Error(`${invite.email} is invited twice in the same batch`);
    }
    seen.add(normalized);

    const existingMember = await memberRepo.findActiveMemberByEmail(
      orgId,
      normalized,
    );
    if (existingMember) {
      throw new Error(`${invite.email} is already a member of this organization`);
    }

    const existingInvitation = await invitationRepo.findPendingInvitationByEmail(
      orgId,
      normalized,
    );
    if (existingInvitation) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }
}

