1	/**
2	 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
5	 */
6	import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
7	import { emit } from "@/lib/event-bus";
8	import { hashToken, randomToken } from "@/lib/hash";
9	import { assertCan } from "@/lib/permissions";
10	import { consumeRateLimit } from "@/lib/rate-limit";
11	import { assertOrgScope } from "@/lib/tenant";
12	import * as invitationRepo from "@/server/repositories/invitation-repository";
13	import * as memberRepo from "@/server/repositories/member-repository";
14	import * as orgRepo from "@/server/repositories/organization-repository";
15	import * as userRepo from "@/server/repositories/user-repository";
16	import { toIsoTimestamp } from "@/types/common";
17	import { envelope, orgResource, requireFound } from "./_support";
18	import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
19	import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
20	import type { InvitationId, UserId } from "@/types/common";
21	import type { Actor, Invitation, Member } from "@/types/member";
22	
23	/** Token bucket protecting the invite mailer from being used as a spam relay. */
24	const INVITE_BUCKET = "member:invite";
25	
26	/** Default validity of a freshly minted invitation, in days. */
27	const DEFAULT_EXPIRY_DAYS = 14;
28	
29	export async function inviteMember(
30	  actor: Actor,
31	  input: InviteMemberInput,
32	): Promise<Invitation> {
33	  const [invitation] = await inviteMembers(actor, {
34	    orgId: input.orgId,
35	    invites: [{ email: input.email, role: input.role }],
36	  });
37	
38	  if (!invitation) throw new Error("Invitation was not created");
39	  return invitation;
40	}
41	
42	/**
43	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
44	 * five people into a plan with three free seats must fail as a batch rather
45	 * than half-succeeding — and the rate limit is charged per invite.
46	 */
47	export async function inviteMembers(
48	  actor: Actor,
49	  input: InviteMembersInput,
50	): Promise<readonly Invitation[]> {
51	  assertOrgScope(actor, input.orgId);
52	  assertCan(actor, "member:invite", orgResource(input.orgId));
53	
54	  await assertInvitableBatch(input.orgId, input.invites);
55	
56	  const verdict = await consumeRateLimit(
57	    input.orgId,
58	    INVITE_BUCKET,
59	    input.invites.length,
60	  );
61	  if (!verdict.allowed) {
62	    throw new Error(
63	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
64	    );
65	  }
66	
67	  const org = requireFound(
68	    await orgRepo.findOrgById(input.orgId),
69	    "Organization",
70	    input.orgId,
71	  );
72	
73	  const seatsUsed =
74	    (await memberRepo.countActiveMembers(input.orgId)) +
75	    (await invitationRepo.countPendingInvitations(input.orgId));
76	
77	  if (
78	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
79	  ) {
80	    const limits = getPlanLimits(org.plan);
81	    throw new Error(
82	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
83	    );
84	  }
85	
86	  const invitations: Invitation[] = [];
87	
88	  for (const invite of input.invites) {
89	    const token = randomToken(32);
90	    const invitation = await invitationRepo.insertInvitation(
91	      input.orgId,
92	      {
93	        orgId: input.orgId,
94	        email: invite.email,
95	        role: invite.role,
96	        expiresInDays: DEFAULT_EXPIRY_DAYS,
97	      },
98	      actor.userId,
99	      hashToken(token),
100	    );
101	
102	    invitations.push(invitation);
103	
104	    await emit("member.invited", {
105	      orgId: input.orgId,
106	      actorId: actor.userId,
107	      occurredAt: invitation.createdAt,
108	      email: invite.email,
109	      role: invite.role,
110	    });
111	  }
112	
113	  return invitations;
114	}
115	
116	/**
117	 * Refuses the whole batch, up front, when it names the same address twice, or
118	 * an address that already belongs to a current member, or one that already
119	 * has a pending invitation. Comparisons ignore letter case, and a refusal
120	 * here means nothing in the batch is created.
121	 */
122	async function assertInvitableBatch(
123	  orgId: InviteMembersInput["orgId"],
124	  invites: InviteMembersInput["invites"],
125	): Promise<void> {
126	  const seen = new Set<string>();
127	
128	  for (const invite of invites) {
129	    const normalized = invite.email.toLowerCase();
130	
131	    if (seen.has(normalized)) {
132	      throw new Error(`${invite.email} is invited twice in the same batch`);
133	    }
134	    seen.add(normalized);
135	
136	    const existingMember = await memberRepo.findActiveMemberByEmail(
137	      orgId,
138	      normalized,
139	    );
140	    if (existingMember) {
141	      throw new Error(`${invite.email} is already a member of this organization`);
142	    }
143	
144	    const existingInvitation = await invitationRepo.findPendingInvitationByEmail(
145	      orgId,
146	      normalized,
147	    );
148	    if (existingInvitation) {
149	      throw new Error(`${invite.email} already has a pending invitation`);
150	    }
151	  }
152	}
153	
154	/**
155	 * Accepting runs unauthenticated: the token is the credential, so there is no
156	 * `Actor` to scope against and every check has to come off the stored row.
157	 */
158	export async function acceptInvitation(
159	  userId: UserId,
160	  input: AcceptInvitationTokenInput,
161	): Promise<Member> {
162	  const invitation = requireFound(
163	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
164	    "Invitation",
165	    "token",
166	  );
167	
168	  if (invitation.revokedAt !== null) {
169	    throw new Error("That invitation has been revoked");
170	  }
171	  if (invitation.acceptedAt !== null) {
172	    throw new Error("That invitation has already been accepted");
173	  }
174	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
175	    throw new Error("That invitation has expired");
176	  }
177	
178	  const org = await orgRepo.findOrgById(invitation.orgId);
179	  if (!org || org.archivedAt !== null) {
180	    throw new Error("That workspace no longer exists");
181	  }
182	
183	  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
184	  if (user.email.toLowerCase() !== invitation.email.toLowerCase()) {
185	    throw new Error("This invitation was sent to a different email address");
186	  }
187	
188	  const now = toIsoTimestamp(new Date());
189	
190	  const existing = await memberRepo.findMemberIncludingArchived(
191	    invitation.orgId,
192	    userId,
193	  );
194	  if (existing && existing.archivedAt === null) return existing;
195	
196	  const member = existing
197	    ? await memberRepo.reviveMember(
198	        invitation.orgId,
199	        existing.id,
200	        invitation.role,
201	        invitation.invitedBy,
202	        now,
203	      )
204	    : await memberRepo.insertMember(
205	        invitation.orgId,
206	        userId,
207	        invitation.role,
208	        invitation.invitedBy,
209	      );
210	
211	  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);
212	
213	  await emit("member.joined", {
214	    ...envelope(invitation.orgId, userId),
215	    memberId: member.id,
216	    userId,
217	    role: member.role,
218	  });
219	
220	  return member;
221	}
222	
223	export async function revokeInvitation(
224	  actor: Actor,
